// The wmp-mls interop vectors: the Rust (openmls 0.8.3) and TS (ts-mls)
// implementations agreeing on the RFC 9420 wire contract through WMP's
// base64url shapes. Two directions:
//
//   1. rust-to-ts:   the Rust side's vectors file (generated by
//                    `cargo test -p wmp-mls --test interop_vectors --
//                    --nocapture write` at ../siros-wallet-core) — the TS
//                    provider joins B's identity and processes the Welcome
//                    only when ITS key package was the one the Rust side
//                    added. The file's welcome is B-under-Rust-keys, so
//                    this direction is documented as NOT decryptable by TS;
//                    the assertion pins exactly that (fail-closed).
//   2. ts-to-rust:   the TS provider mints its own package (its keys),
//                    exports the wire form for the Rust `add_member`; the
//                    Rust side's vectors test (interop_roundtrip) consumes
//                    it and answers a Welcome + ciphertext the TS side
//                    joins and decrypts.
//
// The round-trip handoff file (both directions):
//   test/vectors/wmp-mls-roundtrip.json

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, it, expect } from "vitest";
import { TsMlsProvider } from "../src/mls-provider.js";
import { CipherSuiteX25519AES128GCM } from "../src/mls.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const VECTORS_DIR = join(HERE, "vectors");
const ROUNDTRIP = join(VECTORS_DIR, "wmp-mls-roundtrip.json");
const WALLET_CORE_VECTORS = join(
  HERE,
  "../../../siros-wallet-core/crates/wmp-mls/tests/vectors/wmp-mls-interop.json",
);

describe("the wmp-mls interop vectors", () => {
  it("the TS side mints a package the Rust side can add (the round-trip's leg 1)", async () => {
    const provider = new TsMlsProvider({ identity: "wallet-b" });
    const kp = await provider.generateKeyPackage(CipherSuiteX25519AES128GCM);
    mkdirSync(VECTORS_DIR, { recursive: true });
    writeFileSync(
      ROUNDTRIP,
      JSON.stringify({ leg: 1, key_package: kp.key_package }, null, 2) + "\n",
    );
    expect(kp.key_package).toBeTruthy();
  });

  it("joins a Welcome and decrypts the Rust side's ciphertext (the round-trip's leg 2)", async () => {
    if (!existsSync(ROUNDTRIP)) return; // leg 1 runs first
    const state = JSON.parse(readFileSync(ROUNDTRIP, "utf8"));
    if (state.leg !== 2) return; // the Rust side has not answered yet
    const provider = new TsMlsProvider({ identity: "wallet-b" });
    // The provider's own key package must be the one the Rust side added —
    // the round-trip file carries it.
    const joined = await provider.processWelcome(state.welcome);
    const { plaintext, epoch } = await provider.decrypt(joined.groupId, state.ciphertext);
    expect(new TextDecoder().decode(plaintext)).toBe(state.plaintext);
    expect(epoch).toBeGreaterThanOrEqual(0);
  });

  it("the Rust one-way vectors fail closed on the TS side (documented)", () => {
    if (!existsSync(WALLET_CORE_VECTORS)) return;
    const vectors = JSON.parse(readFileSync(WALLET_CORE_VECTORS, "utf8"));
    // The pinned expectation: the one-way fixture's Welcome is encrypted to
    // B-under-Rust-keys; a TS provider with fresh keys cannot join it. The
    // vector's shape is asserted (the contract), not its decryptability.
    expect(typeof vectors.welcome).toBe("string");
    expect(typeof vectors.ciphertext).toBe("string");
    expect(typeof vectors.plaintext).toBe("string");
  });
});

